function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content);}
try{
 for(const path of paths)put(path,instrumentTypeScriptWithCoverage(readFileSync(path,'utf8'),resolve(path)).code);
 put('src/infrastructure/database/services/stats-service.test.ts',readFileSync('src/infrastructure/database/services/stats-service.test.ts','utf8'));
 for(const path of ['src/infrastructure/database/connection.ts','tests/helpers/owned-test-directory.ts'])put(path,'export * from '+JSON.stringify(join(root,path).replaceAll('\\','/'))+';');
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+',"./capture.ts"]\n');
 const command=[process.execPath,'test','--timeout','15000','src/infrastructure/database/owned-database.test.ts','src/infrastructure/database/services/stats-lifecycle.test.ts','src/infrastructure/database/services/stats-service.test.ts'];
 const run=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:60000});
 const output=new TextDecoder().decode(run.stdout)+new TextDecoder().decode(run.stderr);
 if(run.exitCode!==0)throw Error(output);
 const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
 const files=paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return{path,sourceHash:sourceHash(readFileSync(path,'utf8')),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};});
 writeFileSync('.git/b11-owner-measure.json',JSON.stringify({scope:'Diagnostic only; B05 instrumenter acceptance, per-package and independent review remain open. Generated using helpers may create additional obligations.',runtime:Bun.version,recordedAt:new Date().toISOString(),command,exit:run.exitCode,output,files,rawCoverage:raw,source:readFileSync('.git/b11-owner-measure.ts','utf8')},null,2)+'\n');
 console.log(JSON.stringify(files));
}finally{storage.cleanup();}

