import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,dirname} from 'node:path';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-owner-faults-');
const owner='src/infrastructure/database/owned-database.ts',stats='src/infrastructure/database/services/stats-service.ts';
const paths=[owner,stats,'src/infrastructure/database/owned-database.test.ts','src/infrastructure/database/services/stats-lifecycle.test.ts'];
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
const faults=[
 {name:'missing-resource-registration',path:owner,from:'owned.add(statement);',to:'void statement;'},
 {name:'finalized-resource-retained',path:owner,from:'owned.delete(this);',to:'void this;'},
 {name:'native-finalization-skipped',path:owner,from:'finalize.call(this);',to:'void finalize;'},
 {name:'close-skips-owned-finalizers',path:owner,from:'this.finalizeStatements();',to:'void this;'},
 {name:'finalizer-errors-swallowed',path:owner,from:'failures.push(error);',to:'void error;'},
 {name:'failed-resource-forgotten',path:owner,from:'failures.push(error);',to:'failures.push(error); this.statements.delete(statement);'},
 {name:'other-finalizers-not-attempted',path:owner,from:'failures.push(error);',to:'throw error;'},
 ...['sizeStatement','projectStatement','toolUsesStatement'].map(name=>({name:'stats-retains-'+name,path:stats,from:'using '+name+' =',to:'const '+name+' ='})),
];
const runs:any[]=[];
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content);}
try{
 for(const [path,content]of originals)put(path,content);
 put('tests/helpers/owned-test-directory.ts','export * from '+JSON.stringify(join(root,'tests/helpers/owned-test-directory.ts').replaceAll('\\','/'))+';');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+']\n');
 for(const fault of [null,...faults]){
  for(const [path,content]of originals)put(path,content);
  if(fault){const original=originals.get(fault.path)!;if(original.split(fault.from).length!==2)throw Error('Ambiguous fault '+fault.name);put(fault.path,original.replace(fault.from,fault.to));}
  const command=[process.execPath,'test','--timeout','15000','src/infrastructure/database/owned-database.test.ts','src/infrastructure/database/services/stats-lifecycle.test.ts'];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:45000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);
  runs.push({fault,command,exit:child.exitCode,output});
  if(fault ? child.exitCode===0||!output.includes('(fail)') : child.exitCode!==0)throw Error('Unexpected fault result '+JSON.stringify(fault)+'\n'+output);
 }
 writeFileSync('.git/b11-owner-faults.json',JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,scope:'Equivalent targeted decision checks; not exhaustive mutation or final independent review.',sourceInputs:paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),runs,source:readFileSync('.git/b11-owner-faults.ts','utf8')},null,2)+'\n');
 console.log(JSON.stringify(runs.map(run=>({name:run.fault?.name??'baseline',exit:run.exit}))));
}finally{storage.cleanup();}

